// ── SUB · CRM Region Mirror ─ Resolver Destino Región ────────────────────────
// Misma lógica de resolución de sucursal que el Sucursal Mirror, pero el
// destino es la base REGIONAL leída de suc.crm_base_id_region (sin mapeo en código).

function F(r){ return (r && r.fields && typeof r.fields === 'object') ? r.fields : (r || {}); }
function norm(s){ return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim(); }
function hash(str){ let h=5381; for(let i=0;i<str.length;i++){ h=((h<<5)+h)+str.charCodeAt(i); h=h&h; } return String(h>>>0); }

const trig = $('When Executed by Another Workflow').first().json;
const uid  = String(trig.user_id_canal || '').trim();

const out = (extra) => [{ json: Object.assign({ espejar:false, user_id_canal:uid }, extra) }];

if (!uid) return out({ motivo:'sin_user_id_canal' });

// ── estado previo del espejo regional ─────────────────────────────────────
let prev = { h:null, b:null };
try {
  const raw = $('Redis · Get Region Mirror State').first().json.mirror_state;
  if (raw) prev = (typeof raw === 'string') ? JSON.parse(raw) : raw;
} catch(e) {}

// ── lead maestro ──────────────────────────────────────────────────────────
let leadRec = null;
try { leadRec = $('Airtable · Get Lead').all().map(i=>i.json).filter(r=>r && r.id)[0] || null; } catch(e) {}
if (!leadRec) return out({ motivo:'lead_no_encontrado' });
const L = F(leadRec);

// ── catálogos ─────────────────────────────────────────────────────────────
const sucs = $('Airtable · Get Sucursales').all().map(i=>i.json).filter(r=>r && r.id).map(r=>({ id:r.id, ...F(r) }));
let asesores = [];
try { asesores = $('Airtable · Get Asesores Maestro').all().map(i=>i.json).filter(r=>r && r.id).map(r=>({ id:r.id, ...F(r) })); } catch(e) {}

// ── resolver sucursal (misma lógica que Sucursal Mirror) ──────────────────
let suc = null, via = '';

const linkRec = Array.isArray(L.sucursal_interes) ? L.sucursal_interes[0] : null;
if (linkRec) { suc = sucs.find(s => s.id === linkRec) || null; if (suc) via = 'link_lead'; }

if (!suc && trig.sucursal_id_hint) {
  const c = norm(trig.sucursal_id_hint);
  suc = sucs.find(s => norm(s.sucursal_id) === c) || null;
  if (suc) via = 'hint_main';
}

if (!suc) {
  const ciudad = norm(L.ciudad || trig.ciudad_hint || '');
  if (ciudad) {
    let cand = sucs.filter(s => norm(s.ciudad) === ciudad);
    if (!cand.length) {
      cand = sucs.filter(s => String(s.cobertura_colonias||'').split(',').map(x=>norm(x)).filter(Boolean).includes(ciudad));
    }
    if (cand.length === 1) { suc = cand[0]; via = 'ciudad'; }
    else if (cand.length > 1) {
      const col = norm(L.colonia || '');
      if (col.length >= 4) {
        const p = cand.filter(s => norm(s.nombre).includes(col) || norm(s.sucursal_id) === col);
        if (p.length === 1) { suc = p[0]; via = 'colonia'; }
      }
      // Para región NO necesitamos la sucursal exacta:
      // si todas las candidatas comparten crm_base_id_region, tomamos cualquiera.
      if (!suc) {
        const regBases = [...new Set(cand.map(c => String(c.crm_base_id_region || '').trim()).filter(Boolean))];
        if (regBases.length === 1) {
          suc = cand[0]; // Misma región, tomamos cualquiera
          via = 'ciudad_misma_region';
        } else {
          return out({ motivo:'ciudad_ambigua_multi_region', ciudad, candidatas: cand.map(c=>c.sucursal_id) });
        }
      }
    }
  }
}

if (!suc) return out({ motivo:'sin_sucursal' });

// ── resolver región: directo de la columna crm_base_id_region ─────────────
const baseRegion = String(suc.crm_region_id || '').trim();
if (!baseRegion || !/^app[A-Za-z0-9]{14}$/.test(baseRegion)) {
  return out({ motivo:'sin_region_configurada', sucursal_id: suc.sucursal_id });
}

// ── asesor: recId del maestro → código asesor_id ──────────────────────────
const aRec = Array.isArray(L.asesor_asignado) ? L.asesor_asignado[0] : null;
const aObj = aRec ? asesores.find(a => a.id === aRec) : null;
const asesor_id_codigo = aObj ? String(aObj.asesor_id || '') : '';

// ── payload espejo ────────────────────────────────────────────────────────
const raw = {
  user_id_canal:              uid,
  nombre:                     L.nombre,
  canal_origen:               L.canal_origen,
  conversation_id:            L.conversation_id,
  email:                      L.email,
  telefono:                   L.telefono,
  ciudad:                     L.ciudad,
  colonia:                    L.colonia,
  etapa_pipeline:             L.etapa_pipeline,
  lead_score:                 L.lead_score,
  score_maximo:               L.score_maximo,
  calificado:                 L.calificado,
  modelo_interes:             L.modelo_interes,
  categoria_interes:          L.categoria_interes,
  uso_principal:              L.uso_principal,
  forma_pago_preferida:       L.forma_pago_preferida,
  enganche_disponible:        L.enganche_disponible,
  presupuesto_declarado:      L.presupuesto_declarado,
  como_conocio:               L.como_conocio,
  signals_acumuladas:         L.signals_acumuladas,
  objeciones_detectadas:      L.objeciones_detectadas,
  ultima_intencion:           L.ultima_intencion,
  lead_summary:               L.lead_summary,
  bot_paused:                 L.bot_paused,
  next_followup_at:           L.next_followup_at,
  last_followup_sent_at:      L.last_followup_sent_at,
  followups_count:            L.followups_count,
  followup_respondido:        L.followup_respondido,
  fecha_primera_interaccion:  L.fecha_primera_interaccion,
  ultima_interaccion:         L.ultima_interaccion,
  utm_source:                 L.utm_source,
  activo:                     (L.activo === undefined ? true : L.activo),
  fecha_asignacion:           L.fecha_asignacion,
  financiera_estado:          L.financiera_estado,
  financiera_link_enviado_at: L.financiera_link_enviado_at,
  financiera_respuesta_at:    L.financiera_respuesta_at,
  financiera_elegida:         L.financiera_elegida,
  financiera_asignada:        L.financiera_elegida,
  sucursal_interes:           suc.sucursal_id,
};

// Nunca mandes vacíos: pisarían datos o rompen dateTime/number/select.
const payload = {};
for (const k of Object.keys(raw)) {
  const v = raw[k];
  if (v === undefined || v === null || v === '') continue;
  payload[k] = v;
}

const h = hash(JSON.stringify(payload) + '|' + asesor_id_codigo + '|region:' + baseRegion);

return [{ json: {
  espejar: true,
  user_id_canal: uid,
  lead_rec_id: leadRec.id,
  base_id: baseRegion,
  base_prev: prev.b || null,
  sucursal_id: suc.sucursal_id,
  sucursal_rec_id: suc.id,
  sucursal_nombre: suc.nombre || '',
  via,
  asesor_id_codigo,
  hash: h,
  hash_prev: prev.h || null,
  cambio: h !== (prev.h || null),
  cambio_region: !!(prev.b && prev.b !== baseRegion),
  payload,
} }];

// Payload final para upsert en base regional.
const R = $('Code · Resolver Destino Region').first().json;
const fields = Object.assign({}, R.payload);

let asesorRegId = null;
try {
  const rows = $('Airtable · Buscar Asesor Región').all().map(i=>i.json).filter(r=>r && r.id);
  if (rows.length) asesorRegId = rows[0].id;
} catch(e) {}
if (asesorRegId) fields.asesor_asignado = [asesorRegId];

return [{ json: fields }];

// Espejo de Citas a base regional.
function F(r){ return (r && r.fields && typeof r.fields==='object') ? r.fields : (r||{}); }
const R = $('Code · Resolver Destino Region').first().json;

let leadRegId=null;
try { const u=$('Airtable · Upsert Lead Región').first().json; if(u && u.id) leadRegId=u.id; } catch(e){}

let asesorRegId=null;
try {
  const rows=$('Airtable · Buscar Asesor Región').all().map(i=>i.json).filter(r=>r&&r.id);
  if(rows.length) asesorRegId=rows[0].id;
} catch(e){}

let citas=[];
try { citas=$('Airtable · Get Citas Lead').all().map(i=>i.json).filter(r=>r&&r.id); } catch(e){}

const out=[];
for (const c of citas) {
  const f=F(c);
  if (!f.cita_id) continue;
  const row = {
    cita_id:              f.cita_id,
    user_id_canal:        R.user_id_canal,
    tipo_cita:            f.tipo_cita,
    fecha_hora_inicio:    f.fecha_hora_inicio,
    estado:               f.estado,
    modelo_interes:       f.modelo_interes,
    notas:                f.notas,
    creada_en:            f.creada_en,
    recordatorio_enviado: f.recordatorio_enviado,
    sucursal:             R.sucursal_id,
  };
  if (leadRegId)   row.lead   = [leadRegId];
  if (asesorRegId) row.asesor = [asesorRegId];

  const limpio={};
  for (const k of Object.keys(row)) {
    const v=row[k];
    if (v===undefined || v===null || v==='') continue;
    limpio[k]=v;
  }
  out.push({ json: limpio });
}
return out;

const R = $('Code · Resolver Destino Region').first().json;
return [{ json: {
  ok: true,
  espejado_en: R.base_id,
  sucursal_id: R.sucursal_id,
  via: R.via,
  asesor_espejado: !!R.asesor_id_codigo,
  cambio_de_region: R.cambio_region,
  user_id_canal: R.user_id_canal,
} }];
